export interface JobConfig {
  name: string | Computed<string>;
  view?: string | Computed<string>;
}

export interface JobAttrs {
  /** Output only. The time when the DataScanJob was created. */
  createTime: string;
  /** The output of a data discovery scan. */
  dataDiscoveryResult: Job_DataDiscoveryResult;
  /** Spec for a data discovery scan. */
  dataDiscoverySpec: Job_DataDiscoverySpec;
  /** The output of a DataDocumentation scan. */
  dataDocumentationResult: Job_DataDocumentationResult;
  /** DataDocumentation scan related spec. */
  dataDocumentationSpec: Job_DataDocumentationSpec;
  /** DataProfileResult defines the output of DataProfileScan. Each field of the table will have field type specific profile result. */
  dataProfileResult: Job_DataProfileResult;
  /** DataProfileScan related setting. */
  dataProfileSpec: Job_DataProfileSpec;
  /** The output of a DataQualityScan. */
  dataQualityResult: Job_DataQualityResult;
  /** DataQualityScan related setting. */
  dataQualitySpec: Job_DataQualitySpec;
  /** Output only. The time when the DataScanJob ended. */
  endTime: string;
  /** Output only. Additional information about the current state. */
  message: string;
  name: string;
  /** Output only. A message indicating partial failure details. */
  partialFailureMessage: string;
  /** Output only. The time when the DataScanJob was started. */
  startTime: string;
  /** Output only. Execution state for the DataScanJob. */
  state: string;
  /** Output only. The type of the parent DataScan. */
  type: string;
  /** Output only. System generated globally unique ID for the DataScanJob. */
  uid: string;
  /** Contains the result of an unstructured data profile scan. */
  unstructuredDataProfileResult: Job_UnstructuredDataProfileResult;
  /** Contains the specification for an unstructured data profile scan. */
  unstructuredDataProfileSpec: Job_UnstructuredDataProfileSpec;
  view: string;
}

export const Job: DataSourceBinding<JobConfig, JobAttrs> = {
  wireType: "google_dataplex_job",
  fields: {
    name: "name",
    view: "view",
  },
};
